export type CurriculumAiTool = "assignment" | "quiz" | "flashcards";
export type CurriculumAiLevel = "easy" | "medium" | "hard";

/** Creates a fresh local seed so repeated requests can use new parameter sets without network access. */
export function createCurriculumGenerationSeed(): number {
  if (globalThis.crypto?.getRandomValues) {
    const value = new Uint32Array(1);
    globalThis.crypto.getRandomValues(value);
    return 1 + ((value[0] ?? 0) % 96);
  }
  return 1 + ((Date.now() ^ Math.floor(Math.random() * 0xffffffff)) >>> 0) % 96;
}

